def transform(grid):
    h,w=len(grid),len(grid[0])
    seen=set(); n=0
    for r in range(h):
        for c in range(w):
            if grid[r][c]==0 or (r,c) in seen: continue
            n+=1; color=grid[r][c]; seen.add((r,c)); stack=[(r,c)]
            while stack:
                y,x=stack.pop()
                for dy in (-1,0,1):
                    for dx in (-1,0,1):
                        yy,xx=y+dy,x+dx
                        if 0<=yy<h and 0<=xx<w and (yy,xx) not in seen and grid[yy][xx]==color:
                            seen.add((yy,xx)); stack.append((yy,xx))
    return [[0]*n]

